process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'meteringco-usage-record-dlq-bucket-sandbox';
import { S3Client, ListObjectsV2Command, GetObjectCommand } from '@aws-sdk/client-s3';
import { PrivateAPIUsageController } from '../../app/src/usage/usage.controller';
import { UsageService } from '../../app/src/usage/usage.service';
import { InvoicesService } from '../../app/src/invoice/invoices.service';
import { CustomerService } from '../../app/src/customer/customer.service';
import { createMock } from '@golevelup/ts-jest';

const BUCKET = 'meteringco-usage-record-dlq-bucket-sandbox';
const client = new S3Client({ region: 'us-east-1' });

const list = async (prefix: string) => {
    const res = await client.send(new ListObjectsV2Command({ Bucket: BUCKET, Prefix: prefix }));
    return (res.Contents || []).map((o) => o.Key as string);
};
const get = async (Key: string) => {
    const res = await client.send(new GetObjectCommand({ Bucket: BUCKET, Key }));
    return JSON.parse(await res.Body!.transformToString());
};

describe('db usage dlq', () => {
    let controller: PrivateAPIUsageController;
    beforeEach(() => {
        controller = new PrivateAPIUsageController(
            createMock<UsageService>(),
            createMock<InvoicesService>(),
            createMock<CustomerService>(),
        );
    });

    it('writes malformed json to the dlq under the source key', async () => {
        const s3Key = `biz-test/${Date.now()}/usage-1.json`;
        const message = '{"timestamp":"2026-02-03T08:05:00Z","customerId":"cus_x","dimensionId":"dim';
        await expect(controller.dbUsage({ message, s3Key })).rejects.toThrow(/Invalid message format/);
        const keys = await list(s3Key);
        expect(keys.length).toBe(1);
        console.log(keys);
        const body = await get(keys[0]);
        console.log(JSON.stringify(body, null, 2));
        expect(body.failedDocument).toEqual({ originalFileContent: message, s3Key });
        expect(body.metadata.orginalProcessedName).toBe(s3Key);
        expect(body.metadata.results).toBe('failed to load data');
    });

    it('does not overwrite a previous rejection of the same source', async () => {
        const s3Key = `biz-test/${Date.now()}/usage-2.json`;
        const message = '{"timestamp":"11/02/2026 08:00","customerId":"cus_y","dimensionId":"d","recordValue":"301"}';
        await expect(controller.dbUsage({ message, s3Key })).rejects.toThrow();
        const first = await list(s3Key);
        await expect(controller.dbUsage({ message, s3Key })).rejects.toThrow();
        const second = await list(s3Key);
        expect(second.length).toBe(2);
        const body = await get(first[0]);
        console.log(JSON.stringify(body.metadata.errorInfo));
        expect(await get(first[0])).toEqual(await get(first[0]));
    });

    it('retains messages with no source file', async () => {
        const message = '{"timestamp":"2026-02-11T22:14:00Z","customerId":"cus_z","recordValue":"4"}';
        const before = await list('meteringco-unknown/');
        await expect(controller.dbUsage({ message })).rejects.toThrow(/Invalid message format/);
        const after = await list('meteringco-unknown/');
        expect(after.length).toBe(before.length + 1);
        const newKey = after.filter((k) => !before.includes(k))[0];
        const body = await get(newKey);
        console.log(newKey, JSON.stringify(body, null, 2));
        expect(body.failedDocument.originalFileContent).toBe(message);
        expect(newKey.startsWith(body.metadata.orginalProcessedName)).toBe(true);
    });

    it('still rejects when dlq storage refuses the write', async () => {
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'this-bucket-does-not-exist-anywhere';
        await expect(controller.dbUsage({ message: 'not json', s3Key: 'biz-test/x.json' })).rejects.toThrow(
            /Invalid message format/,
        );
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = BUCKET;
    });

    it('happy path still loads usage', async () => {
        const svc = createMock<UsageService>();
        const c = new PrivateAPIUsageController(svc, createMock<InvoicesService>(), createMock<CustomerService>());
        const message = JSON.stringify({
            timestamp: '2026-02-11T22:14:00Z',
            customerId: 'cus_z',
            dimensionId: 'dim',
            recordValue: '4',
        });
        await c.dbUsage({ message, s3Key: 'biz-test/ok.json' });
        expect(svc.create).toHaveBeenCalledWith(expect.objectContaining({ businessID: 'biz-test' }));
    });
});
